public sealed class MappingRow { public int Pitch { get; set; } public string Note=>Notes.Name(Pitch); public string Key { get; set; }=""; }
public record HotkeyPreferences(HotkeyModifiers Modifiers, int ToggleFunction, int StopFunction);
public record PlayerPreferences(KeyboardMapping Profile,int Octave);
public partial class MainWindow : Window, IDisposable {
 readonly WindowsKeyboardInput input=new(); readonly PlaybackEngine engine; readonly PlaybackHotkeyController hotkeyController;
 readonly MidiImporter importer=new(); readonly ProfileStore store=new(); readonly ObservableCollection<MappingRow> rows=new();
 readonly DispatcherTimer timer=new(){Interval=TimeSpan.FromMilliseconds(50)};
 MidiSong? song; TimeSpan songDuration; long lastRollPositionTicks=-1; KeyboardMapping profile=new(){Name="Empty mapping",Verified=false}; CancellationTokenSource? arm; int importGeneration,diagnosticTick; PlaybackState lastDisplayedState=PlaybackState.Idle;
 GlobalHotkeyService? hotkeys; HwndSource? source; CancellationTokenSource? pendingHotkey; bool disposed; HotkeyPreferences currentHotkeys=new(HotkeyModifiers.Control|HotkeyModifiers.Alt,8,9);
 static bool WorkflowMode=>Array.IndexOf(Environment.GetCommandLineArgs(),"--workflow-test")>=0;
 static string AppDataRoot { get { var args=Environment.GetCommandLineArgs(); int index=Array.IndexOf(args,"--workflow-test"); if(index>=0) { if(index+2>=args.Length || !Path.IsPathFullyQualified(args[index+1]) || !Directory.Exists(args[index+1]))throw new InvalidOperationException("A pre-existing absolute workflow test directory and MIDI fixture are required."); return Path.Combine(Path.GetFullPath(args[index+1]),"KEYNOTE"); } return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"KEYNOTE"); } }
 static string SettingsPath=>Path.Combine(AppDataRoot,"hotkeys.json");
 static string PlayerSettingsPath=>Path.Combine(AppDataRoot,"player.json");
 bool loadingPreferences=true;
 int Shift=>Octave?.SelectedItem is ComboBoxItem item && int.TryParse(item.Content.ToString(),out int n)?n:0;
 public MainWindow() {
  InitializeComponent(); engine=new(input); InitializeOnline(); hotkeyController=new(()=>engine.State,()=>input.IsTargetForeground,StartImmediate,engine.Pause,engine.Resume,EmergencyStop,engine.AcknowledgeInputPause);
  for(int i=0;i<128;i++)rows.Add(new(){Pitch=i}); MappingGrid.ItemsSource=rows;
  ToggleKey.ItemsSource=Enumerable.Range(1,12).Select(i=>$"F{i}").ToArray(); StopKey.ItemsSource=Enumerable.Range(1,12).Select(i=>$"F{i}").ToArray();
  try { if(File.Exists(SettingsPath)) currentHotkeys=JsonSerializer.Deserialize<HotkeyPreferences>(File.ReadAllText(SettingsPath)) ?? currentHotkeys; } catch(Exception ex) when(ex is IOException or UnauthorizedAccessException or JsonException) { HotkeyStatus.Text="Could not load saved shortcuts: "+ex.Message; }
  if(currentHotkeys.ToggleFunction is <1 or >12 || currentHotkeys.StopFunction is <1 or >12) currentHotkeys=new(HotkeyModifiers.Control|HotkeyModifiers.Alt,8,9);
  ShowPreferences(currentHotkeys); RestorePlayerPreferences(); loadingPreferences=false; timer.Tick+=(_,_)=>UpdateStatus(); timer.Start(); RefreshWindows(null!,null!); UpdateMapping();
 }
 void RestorePlayerPreferences() { try { if(!File.Exists(PlayerSettingsPath))return; var saved=JsonSerializer.Deserialize<PlayerPreferences>(File.ReadAllText(PlayerSettingsPath)); if(saved?.Profile?.Keys==null || saved.Octave is < -2 or > 2 || saved.Profile.Keys.Any(k=>k.Key is <0 or >127 || !KeyboardMapping.IsValidKey(k.Value)) || saved.Profile.Duplicates().Any())throw new InvalidDataException("Invalid saved mapping."); profile=saved.Profile; foreach(var row in rows)row.Key=profile.Keys.GetValueOrDefault(row.Pitch,""); Octave.SelectedIndex=saved.Octave+2; MappingGrid.Items.Refresh(); } catch(Exception ex) when(ex is IOException or UnauthorizedAccessException or JsonException or InvalidDataException) { CalibrationStatus.Text="Could not restore mapping: "+ex.Message; } }
 void SavePlayerPreferences() { if(loadingPreferences)return; try { Directory.CreateDirectory(AppDataRoot); var temp=PlayerSettingsPath+".tmp"; File.WriteAllText(temp,JsonSerializer.Serialize(new PlayerPreferences(profile,Shift))); File.Move(temp,PlayerSettingsPath,true); } catch(Exception ex) when(ex is IOException or UnauthorizedAccessException) { CalibrationStatus.Text="Could not save mapping: "+ex.Message; } }
 void OnSourceInitialized(object? s,EventArgs e) { if(WorkflowMode) { HotkeyStatus.Text="Workflow test mode: hotkeys disabled."; return; } if(Environment.GetCommandLineArgs().Contains("--smoke-test")) { HotkeyStatus.Text="Smoke test mode: hotkeys disabled."; _=Task.Delay(1000).ContinueWith(_=>Dispatcher.InvokeAsync(Close)); return; } source=HwndSource.FromHwnd(new WindowInteropHelper(this).Handle); source.AddHook(WindowMessage); hotkeys=new GlobalHotkeyService(new WindowsHotkeyPlatform(source.Handle)); hotkeys.Triggered+=HandleHotkey; RegisterHotkeys(currentHotkeys,false); }
 nint WindowMessage(nint hwnd,int message,nint wParam,nint lParam,ref bool handled) { if(message==0x0312) { hotkeys?.Dispatch(wParam.ToInt32()); handled=true; } return 0; }
 async void HandleHotkey(HotkeyCommand command) { try {
  if(command==HotkeyCommand.EmergencyStop) { pendingHotkey?.Cancel(); await hotkeyController.EmergencyStop(); return; }
  if(engine.State==PlaybackState.Playing) { hotkeyController.Toggle(); return; }
  if(pendingHotkey!=null) return;
  pendingHotkey=new CancellationTokenSource(); var current=pendingHotkey; var shortcut=new Hotkey(currentHotkeys.Modifiers,(uint)(0x6F+currentHotkeys.ToggleFunction));
  try { if(await HotkeyReleaseGate.WaitAsync(()=>WindowsHotkeyPlatform.AreReleased(shortcut),current.Token)) hotkeyController.Toggle(); else Status.Text="Release the shortcut keys and try again."; } finally { if(ReferenceEquals(pendingHotkey,current))pendingHotkey=null; current.Dispose(); }
 } catch(OperationCanceledException) { } catch(Exception ex) { Status.Text=ex.Message; } }
 void ShowPreferences(HotkeyPreferences p) { HotkeyCtrl.IsChecked=p.Modifiers.HasFlag(HotkeyModifiers.Control); HotkeyAlt.IsChecked=p.Modifiers.HasFlag(HotkeyModifiers.Alt); HotkeyShift.IsChecked=p.Modifiers.HasFlag(HotkeyModifiers.Shift); ToggleKey.SelectedIndex=p.ToggleFunction-1; StopKey.SelectedIndex=p.StopFunction-1; }
 void ApplyHotkeys(object s,RoutedEventArgs e) { var modifiers=(HotkeyCtrl.IsChecked==true?HotkeyModifiers.Control:0)|(HotkeyAlt.IsChecked==true?HotkeyModifiers.Alt:0)|(HotkeyShift.IsChecked==true?HotkeyModifiers.Shift:0); RegisterHotkeys(new(modifiers,ToggleKey.SelectedIndex+1,StopKey.SelectedIndex+1),true); }
 void RegisterHotkeys(HotkeyPreferences p,bool save) { if(hotkeys==null)return; var toggle=new Hotkey(p.Modifiers,(uint)(0x6F+p.ToggleFunction)); var stop=new Hotkey(p.Modifiers,(uint)(0x6F+p.StopFunction)); if(!hotkeys.Register(toggle,stop,out var error)) { HotkeyStatus.Text=error; ShortcutHint.Text="Shortcut registration failed. Check Settings: "+error; ShowPreferences(currentHotkeys); return; } currentHotkeys=p; ShortcutHint.Text=toggle.ToString(); StopHint.Text=stop.ToString(); HotkeyStatus.Text=$"Registered: {toggle} (play / pause / resume)  |  {stop} (emergency stop)"; if(save) try { Directory.CreateDirectory(Path.GetDirectoryName(SettingsPath)!); File.WriteAllText(SettingsPath,JsonSerializer.Serialize(p)); } catch(Exception ex) when(ex is IOException or UnauthorizedAccessException) { HotkeyStatus.Text+=". Could not save: "+ex.Message; } }
 void Browse(object s,RoutedEventArgs e) { var d=new OpenFileDialog{Filter="MIDI files|*.mid;*.midi"}; if(d.ShowDialog()==true)Import(d.FileName); }
 void OnDrop(object s,DragEventArgs e) { if(e.Data.GetData(DataFormats.FileDrop) is string[] files && files.Length>0)Import(files[0]); }
 async void Import(string path) { await ImportSongAsync(path,null); }
 async Task<bool> ImportSongAsync(string path,IReadOnlyCollection<int>? tracks,string? displayName=null,CancellationToken token=default) { var generation=++importGeneration; hotkeyController.SetReady(false); try { arm?.Cancel(); await engine.StopAsync(); token.ThrowIfCancellationRequested(); var loaded=await Task.Run(()=>importer.Import(path),token); token.ThrowIfCancellationRequested(); if(generation!=importGeneration)return false; if(tracks!=null) { loaded=loaded with { Tracks=loaded.Tracks.Where(t=>tracks.Contains(t.Index)).ToArray() }; if(!loaded.Notes.Any())throw new InvalidDataException("Select at least one track containing notes."); } if(!string.IsNullOrWhiteSpace(displayName))loaded=loaded with { Name=displayName }; ApplyPlayerSong(loaded,null); return true; } catch(OperationCanceledException) { if(generation==importGeneration)Status.Text="Import cancelled."; return false; } catch(Exception ex) { if(generation==importGeneration)Status.Text="Import failed: "+ex.Message; return false; } }
 void ApplyPlayerSong(MidiSong loaded,LibraryEntry? entry) { song=loaded; songDuration=loaded.Duration; lastRollPositionTicks=-1; SongTitle.Text=loaded.Name; SongInfo.Text=$"{loaded.Tracks.Count} tracks  •  {loaded.Notes.Count()} notes  •  {FormatTime(songDuration)}"; SongSource.Text=entry==null?"Local MIDI":$"{entry.Artist}  •  {entry.Provider}  •  {entry.License}  •  SHA-256 {entry.Sha256}"; SongSource.ToolTip=entry==null?"Local MIDI":$"Artist: {entry.Artist}\nSource: {entry.Source}\nLicense: {entry.License}\nSHA-256: {entry.Sha256}"; Roll.Song=loaded; Roll.InvalidateVisual(); EmptyState.Visibility=Visibility.Collapsed; LoadedWorkspace.Visibility=Visibility.Visible; Duration.Text=FormatTime(songDuration); UpdateMapping(); hotkeyController.SetReady(true); }

 void SyncProfile() { profile.Keys=rows.Where(r=>!string.IsNullOrWhiteSpace(r.Key)).ToDictionary(r=>r.Pitch,r=>r.Key.Trim().ToUpperInvariant()); }
 void UpdateMapping() { if(MappingGrid==null)return; SyncProfile(); var missing=song==null?0:profile.Missing(song,Shift).Length; PlayerMapping.Text=$"Mapping: {profile.Name} · {(profile.Verified?"verified":"not verified")} · {missing} unmapped pitches"+(missing>0?" ("+string.Join(", ",profile.Missing(song!,Shift).Select(Notes.Name))+")":""); MappingSummary.Text=$"{missing} missing • {profile.Duplicates().Count()} duplicate keys • {(profile.Verified?"user-marked verified":"unverified")}"+(song!=null && missing>0?"\nUnsupported or unmapped MIDI pitches: "+string.Join(", ",profile.Missing(song,Shift).Select(p=>$"{p} ({Notes.Name(p)})")):""); if(VerifiedCheck!=null)VerifiedCheck.IsChecked=profile.Verified; Roll.Mapping=profile; Roll.Octave=Shift; Roll.InvalidateVisual(); UpdatePreflight(); if(engine!=null && song!=null && engine.State is PlaybackState.Idle or PlaybackState.Stopped or PlaybackState.Ready)Status.Text=!profile.Verified?"Manually verify your mapping for this piano before playback.":missing>0?"Map every song note before playback.":profile.Duplicates().Any() || profile.Keys.Values.Any(k=>!KeyboardMapping.IsValidKey(k))?"Resolve invalid or duplicate key assignments before playback.":"Ready"; }
 void MappingEdit(object s,DataGridCellEditEndingEventArgs e) { InvalidateMappingSession(); profile.Verified=false; Dispatcher.BeginInvoke(()=> { UpdateMapping(); SavePlayerPreferences(); },DispatcherPriority.Background); }
 void CaptureMappingKey(object s,KeyEventArgs e) { if(Keyboard.Modifiers is not (ModifierKeys.None or ModifierKeys.Shift))return; var key=e.Key==Key.System?e.SystemKey:e.Key; string? value=key is >=Key.A and <=Key.Z ? ((char)('A'+(int)key-(int)Key.A)).ToString() : key is >=Key.D0 and <=Key.D9 ? ((char)('0'+(int)key-(int)Key.D0)).ToString() : null; if(value!=null && s is TextBox box) { box.Text=(Keyboard.Modifiers==ModifierKeys.Shift?"SHIFT+":"")+value; box.CaretIndex=box.Text.Length; e.Handled=true; } }
 void VerifyProfile(object s,RoutedEventArgs e) { SyncProfile(); if(VerifiedCheck.IsChecked==true && (profile.Keys.Count==0 || profile.Keys.Values.Any(k=>!KeyboardMapping.IsValidKey(k)) || profile.Duplicates().Any() || (song!=null && profile.Missing(song,Shift).Length>0))) { VerifiedCheck.IsChecked=false; CalibrationStatus.Text="Complete the mapping and resolve invalid or duplicate assignments before marking it verified."; } profile.Verified=VerifiedCheck.IsChecked==true; if(!profile.Verified)InvalidateMappingSession(); UpdateMapping(); SavePlayerPreferences(); }
 void InvalidateMappingSession() { arm?.Cancel(); if(engine!=null && engine.State is PlaybackState.Playing or PlaybackState.Paused) { _=engine.StopAsync(); Status.Text="Playback stopped because the mapping changed."; } }
 void MappingChanged(object s,SelectionChangedEventArgs e) { if(Roll!=null) { InvalidateMappingSession(); UpdateMapping(); SavePlayerPreferences(); } }
 void StartImmediate() { if(song==null)throw new InvalidOperationException("Import a MIDI file first."); SyncProfile(); if(!profile.Verified)throw new InvalidOperationException("Manually verify your mapping for this piano before playback."); if(input.Target==0)throw new InvalidOperationException("Select a Roblox window on the Player screen."); engine.Speed=Speed.Value; engine.Start(song,profile,Shift); Status.Text="Playing"; }
 async void Play(object s,RoutedEventArgs e) { CancellationTokenSource? operation=null; try { if(song==null)throw new InvalidOperationException("Import a MIDI file first."); SyncProfile(); if(!profile.Verified)throw new InvalidOperationException("Manually verify your mapping for this piano before playback."); _=PlaybackEngine.BuildEvents(song,profile,Shift); if(input.Target==0)throw new InvalidOperationException("Select a Roblox window on the Player screen."); if(engine.State is PlaybackState.Playing or PlaybackState.Paused)throw new InvalidOperationException("Stop the current session before starting another."); arm?.Cancel(); arm=operation=new(); var token=operation.Token; hotkeyController.SetReady(false); Status.Text="Armed — focus the selected Roblox window to begin."; while(!input.IsTargetForeground)await Task.Delay(50,token); token.ThrowIfCancellationRequested(); StartImmediate(); } catch(OperationCanceledException) { } catch(Exception ex) { if(song!=null && engine.State is PlaybackState.Idle or PlaybackState.Stopped)hotkeyController.SetReady(true); Status.Text=ex.Message; } finally { if(operation!=null) { if(ReferenceEquals(arm,operation))arm=null; operation.Dispose(); } } }
 void GoDiscover(object s,RoutedEventArgs e)=>MainTabs.SelectedIndex=1;
 void GoLibrary(object s,RoutedEventArgs e)=>MainTabs.SelectedIndex=3;
 void GoMapping(object s,RoutedEventArgs e)=>MainTabs.SelectedIndex=4;
 void GoSettings(object s,RoutedEventArgs e)=>MainTabs.SelectedIndex=5;
 void PlayPause(object s,RoutedEventArgs e) { if(engine.State is PlaybackState.Playing or PlaybackState.Paused)Pause(s,e); else Play(s,e); }
 void Pause(object s,RoutedEventArgs e) { if(engine.State==PlaybackState.Playing)engine.Pause(); else if(engine.State==PlaybackState.Paused)engine.Resume(); }
 async Task EmergencyStop() { pendingHotkey?.Cancel(); arm?.Cancel(); await engine.StopAsync(); Status.Text=engine.Error ?? "Stopped"; CalibrationStatus.Text=engine.Error ?? "Stopped"; }
 async void Stop(object s,RoutedEventArgs e) { await hotkeyController.EmergencyStop(); }
 void SpeedChanged(object s,RoutedPropertyChangedEventArgs<double> e) { if(SpeedText!=null)SpeedText.Text=$"{e.NewValue:P0}"; if(engine!=null)engine.Speed=e.NewValue; }
 static string FormatTime(TimeSpan time)=>time.TotalHours>=1?$"{(int)time.TotalHours}:{time.Minutes:00}:{time.Seconds:00}":$"{(int)time.TotalMinutes}:{time.Seconds:00}";
 void UpdateStatus() { var state=engine.State; PlaybackButton.Content=state==PlaybackState.Playing?"Pause":state==PlaybackState.Paused?"Resume":"Play"; var selectedWindow=Windows.SelectedItem as RobloxWindow; var connection=selectedWindow==null?"No Roblox window selected":input.IsTargetForeground?"Roblox in foreground":"Roblox selected · focus it to play"; ConnectionStatus.Text=connection; ShellStatus.Text=connection; if(state is PlaybackState.Playing or PlaybackState.Paused or PlaybackState.Faulted)Status.Text=engine.Error ?? state.ToString(); else if(state==PlaybackState.Stopped && lastDisplayedState is PlaybackState.Playing or PlaybackState.Paused)Status.Text="Stopped"; lastDisplayedState=state; if(song!=null) { var current=engine.Position; var position=current>songDuration?songDuration:current; Elapsed.Text=FormatTime(position); Progress.Value=songDuration.TotalSeconds>0?Math.Clamp(position.TotalSeconds/songDuration.TotalSeconds*100,0,100):0; if(position.Ticks!=lastRollPositionTicks && diagnosticTick%2==0) { lastRollPositionTicks=position.Ticks; Roll.Position=position; Roll.InvalidateVisual(); } }
  if(++diagnosticTick%5==0) { var d=engine.Diagnostics; var target=Windows.SelectedItem as RobloxWindow; DiagnosticsText.Text=$"Target: {target?.Title ?? "none"}  |  PID: {(target?.ProcessId.ToString(System.Globalization.CultureInfo.InvariantCulture) ?? "—")}\nForeground: {input.IsTargetForeground}  |  State: {state}  |  Held: {string.Join(", ",input.HeldKeys.DefaultIfEmpty("none"))}\nScheduled: {d.Scheduled}  |  Dispatched: {d.Dispatched}  |  Failed: {d.Failed}  |  Late: {d.Late}\nLateness avg / p95 / max: {d.AverageLateMs:F1} / {d.P95LateMs:F0} / {d.MaxLateMs:F1} ms  |  Cleanup failures: {d.CleanupFailures}  |  Focus losses: {d.FocusLosses}"; }
 }
 async void SaveProfile(object s,RoutedEventArgs e) { try { SyncProfile(); var d=new SaveFileDialog{Filter="JSON profile|*.json",FileName="mapping.json"}; if(d.ShowDialog()==true)await store.SaveAsync(d.FileName,profile); } catch(Exception ex) { CalibrationStatus.Text=ex.Message; } }
 async void LoadProfile(object s,RoutedEventArgs e) { try { var d=new OpenFileDialog{Filter="JSON profile|*.json"}; if(d.ShowDialog()!=true)return; InvalidateMappingSession(); profile=await store.LoadAsync(d.FileName); foreach(var r in rows)r.Key=profile.Keys.GetValueOrDefault(r.Pitch,""); MappingGrid.Items.Refresh(); UpdateMapping(); SavePlayerPreferences(); } catch(Exception ex) { MessageBox.Show(ex.Message,"Profile error"); } }
 async void TestKey(object s,RoutedEventArgs e) { if((s as Button)?.Tag is MappingRow row && !string.IsNullOrWhiteSpace(row.Key))await RunCalibration(new[]{row.Key}); }
 async void TestSequence(object s,RoutedEventArgs e) { SyncProfile(); if(profile.Duplicates().Any() || profile.Keys.Values.Any(k=>!KeyboardMapping.IsValidKey(k))) { CalibrationStatus.Text="Resolve duplicate or invalid assignments before testing."; return; } await RunCalibration(profile.Keys.OrderBy(k=>k.Key).Select(k=>k.Value).ToArray()); }
 async Task RunCalibration(string[] keys) { bool restoreReady=hotkeyController.Ready, ownsArm=false; CancellationToken token=default; CancellationTokenSource? operation=null; try { if(keys.Length==0)throw new InvalidOperationException("Assign at least one key first."); if(keys.Any(k=>!KeyboardMapping.IsValidKey(k)))throw new InvalidOperationException("Use A–Z, 0–9, or Shift+key."); if(input.Target==0)throw new InvalidOperationException("Select a Roblox window first."); arm?.Cancel(); arm=operation=new(); token=operation.Token; ownsArm=true; hotkeyController.SetReady(false); await engine.StopAsync(); token.ThrowIfCancellationRequested(); input.ReleaseAll(); CalibrationStatus.Text="Test armed — focus the selected Roblox window. Use the stop hotkey to cancel."; while(!input.IsTargetForeground)await Task.Delay(50,token); foreach(var key in keys) { token.ThrowIfCancellationRequested(); if(!input.IsTargetForeground)throw new InvalidOperationException("Focus lost; calibration stopped."); input.Press(key); try { await Task.Delay(150,token); } finally { input.Release(key); } await Task.Delay(300,token); } CalibrationStatus.Text="Test keys dispatched. Confirm the notes in the game before marking the profile verified."; } catch(OperationCanceledException) { CalibrationStatus.Text="Calibration stopped."; } catch(Exception ex) { CalibrationStatus.Text=ex.Message; } finally { if(ownsArm && !token.IsCancellationRequested)hotkeyController.SetReady(restoreReady); if(operation!=null) { if(ReferenceEquals(arm,operation))arm=null; operation.Dispose(); } } }
 async void StartPlaybackTest(object s,RoutedEventArgs e) { CancellationTokenSource? operation=null; try { SyncProfile(); if(!profile.Verified)throw new InvalidOperationException("Manually verify your mapping for this piano before running playback tests."); if(input.Target==0)throw new InvalidOperationException("Select a Roblox window first."); if(engine.State is PlaybackState.Playing or PlaybackState.Paused)throw new InvalidOperationException("Stop the current session before starting a test."); var kind=(PlaybackTestKind)TestPattern.SelectedIndex; var pitches=profile.Keys.Where(k=>KeyboardMapping.IsValidKey(k.Value)).Select(k=>k.Key-Shift*12).Where(p=>p is >=0 and <=127).Order().ToArray(); var test=PlaybackTestPatterns.Create(kind,pitches); _=PlaybackEngine.BuildEvents(test,profile,Shift); arm?.Cancel(); arm=operation=new CancellationTokenSource(); var token=operation.Token; TestStatus.Text="Test armed — focus the selected Roblox window. Use the stop hotkey to cancel."; while(!input.IsTargetForeground)await Task.Delay(50,token); token.ThrowIfCancellationRequested(); engine.Speed=kind==PlaybackTestKind.Tempo?1:Speed.Value; hotkeyController.SetReady(false); engine.Start(test,profile,Shift); TestStatus.Text=kind switch { PlaybackTestKind.PauseResume=>"Test running: press the play/pause shortcut twice to pause and resume.",PlaybackTestKind.EmergencyStop=>"Test running: press the emergency-stop shortcut.",PlaybackTestKind.Tempo=>"Test running at 120 beats per minute. Observe timing and diagnostics.",_=>"Test running. Verify receipt and audible notes in the game; Windows dispatch alone is not proof." }; } catch(OperationCanceledException) { TestStatus.Text="Test cancelled."; } catch(Exception ex) { TestStatus.Text=ex.Message; } finally { if(operation!=null) { if(ReferenceEquals(arm,operation))arm=null; operation.Dispose(); } } }
 void RefreshWindows(object s,RoutedEventArgs e) { var previous=Windows.SelectedItem as RobloxWindow; var windows=WindowsKeyboardInput.FindWindows(); Windows.ItemsSource=windows; Windows.SelectedItem=windows.FirstOrDefault(w=>previous!=null && w.Handle==previous.Handle && w.ProcessId==previous.ProcessId) ?? (windows.Count==1?windows[0]:null); }
 void WindowSelected(object s,SelectionChangedEventArgs e) { if(input!=null) { var selected=Windows.SelectedItem as RobloxWindow; input.TargetProcessId=selected?.ProcessId ?? 0; input.Target=selected?.Handle ?? 0; } }
 public void Dispose() { if(disposed)return; DisposeOnline(); pendingHotkey?.Cancel(); arm?.Cancel(); engine.Dispose(); hotkeys?.Dispose(); if(source!=null)source.RemoveHook(WindowMessage); timer.Stop(); arm?.Dispose(); pendingHotkey?.Dispose(); disposed=true; GC.SuppressFinalize(this); }
 void OnClosing(object? s,CancelEventArgs e) { try { Dispose(); } catch(Exception ex) { e.Cancel=true; Status.Text="Cleanup failed; retry closing: "+ex.Message; MessageBox.Show(Status.Text,"KEYNOTE",MessageBoxButton.OK,MessageBoxImage.Error); } }
}
